import{z as A,x as p,o,c as B,q as s,j as l,D as n,d as e,s as r,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Dual Chunk Attention 原文","description":"","frontmatter":{"title":"Dual Chunk Attention 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dca-paper.md","filePath":"llm/dca-paper.md","lastUpdated":1791063341000}'),h={name:"llm/dca-paper.md"};function d(c,a,P,u,m,D){const i=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=s('<h1 id="dual-chunk-attention-原文" tabindex="-1">Dual Chunk Attention 原文 <a class="header-anchor" href="#dual-chunk-attention-原文" aria-label="Permalink to &quot;Dual Chunk Attention 原文&quot;">​</a></h1><div class="epigraph"><p>不要缩放 RoPE 的下标或基数；把长序列的相对位置矩阵按块重写，块内、块间、相邻块各用一套仍落在预训练窗里的坐标。</p><footer>—— An 等，Training-Free Long-Context Scaling of Large Language Models，2024</footer></div><p>Chenxin An、Fei Huang、Jun Zhang、Shansan Gong、Xipeng Qiu、Chang Zhou 与 Lingpeng Kong 的论文 <em>Training-Free Long-Context Scaling of Large Language Models</em> 把方法命名为 Dual Chunk Attention（DCA），代码与数据以 ChunkLlama 发布。主张比「再做一个 NTK」更硬：训练免费的 PI/NTK 在超过约 2 倍训练长度后 PPL 明显变差；DCA 让 Llama2 70B 在无续训下处理超过 100k token，并在实用长任务上接近甚至超过昂贵续训模型，相对 GPT-3.5-16k 达到约 94% 的分数。FlashAttention 2 被写成可落地的前提——没有它，70B 在两张 A100 上甚至跑不满长 prefill。本篇按原文的三套相对位置矩阵写；块 wise 工程对照见 <a href="/llm/dual-chunk-attention">Dual Chunk Attention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源长窗续训语料与算力都被闭源实验室拿走，公开权重往往停在 7B/13B。训练免费路线里，StreamingLLM、LM-Infinite 保住局部、丢掉中间，PPL 低但没有长程。PI 与 NTK 在<strong>不微调</strong>时，相对位置被缩小，分辨率差，原文测量：超过约 8k（相对 4k 训练窗）PPL 就明显升。<span class="marginnote">用数字感受这个缺口：模型预训练时见过的相对位置差最大到 4095，而一篇 100k 的长文里，首尾 token 的位置差高达约十万。硬塞进从未见过的坐标，就像让只学过两位数加法的学生直接算五位数——不是不会算，是没见过这种数，错误率自然飙升。</span>能否既看见中间全部键，又让相对位置矩阵的每个元素仍不超过预训练窗 \\(c\\)？</p><p>作者选择不改 \\(\\theta\\)、不除 \\(s\\)，而是重建 Toeplitz 式的相对位置表 \\(M[i][j]=P_q[i]-P_k[j]\\)：同一条序列上，\\(P\\) 按「是否同块、是否相邻块」切换。问题变成三套 \\(P\\) 如何定义，以及如何与 FlashAttention 的分块计算兼容，使 70B 实验做得以成立。</p><h3 id="为何不训练也能上-70b" tabindex="-1">为何不训练也能上 70B <a class="header-anchor" href="#为何不训练也能上-70b" aria-label="Permalink to &quot;为何不训练也能上 70B&quot;">​</a></h3><p>续训 70B 到 100k 在当时对多数实验室不可行。DCA 的正交性实验还表明：已经用 PI/NTK 续训到 32k 的模型，再套 DCA 可以继续外推到约 192k，passkey 与 PPL 仍可用。也就是说方法不是「只救 4k 底座」，也可以叠在已有长窗检查点上。这要求实现不要写死「块长等于 4096」，而要等于该检查点的训练窗。</p><p><span class="marginnote">论文用本文自身当输入出题，以降低预训练污染。读「长上下文理解」表时，应连同这一设定一起看：涨分更可能来自窗口，而不是背过评测集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>序列切成大小 \\(s\\) 的块，\\(s\\) 小于预训练窗 \\(c\\)。三套注意力共用键的位置循环 \\(P_k=[0,\\ldots,s-1]\\) 重复，查询则换编号。</p><h3 id="块内、块间、相邻块" tabindex="-1">块内、块间、相邻块 <a class="header-anchor" href="#块内、块间、相邻块" aria-label="Permalink to &quot;块内、块间、相邻块&quot;">​</a></h3><p><strong>Intra-chunk</strong>：\\(\\lfloor i/s\\rfloor=\\lfloor j/s\\rfloor\\) 时，\\(P_q^{\\mathrm{Intra}}=P_k=(\\cdot\\bmod s)\\)，块内相对位置与训练短窗同构。单独用它等于左截断到一块，PPL 低、没有跨块信息。</p><p><strong>Inter-chunk</strong>：查询与更早的非相邻块交互。给查询另一套 \\(P_q^{\\mathrm{Inter}}\\)，使块级距离被编码成仍小于 \\(c\\) 的相对值，同时块内局部坐标不完全抹平——「很早的一块」与「稍早的一块」可区分，相位却不 OOD。精度低于块内，用于长程。</p><p><strong>Successive-chunk</strong>：仅相邻块。跨块句子、边界指代最怕块间那套较粗的坐标。相邻块使用更接近块内的 \\(P_q^{\\mathrm{Succ}}\\)，并与局部窗 \\(w\\) 配合，在 \\(M\\) 上形成阴影区，减轻接缝裂缝。三类分数进入同一 softmax（或数值稳定地合并）。形式为 \\(s(q,k)=q^\\top R(\\phi(q,k))k/\\sqrt{d}\\)，\\(\\phi\\) 依块关系取三种映射。</p><p>消融（原文图 4）表明：缺 inter 则长程针测差；缺 successive 则边界与 PPL 受伤；三者齐才在 PPL 与 passkey 上同时站住。</p>',16)),(o(),l(E,null,{default:n(()=>[r(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%BD%93%E5%89%8D%E5%9D%97%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20I%5B%22intra%3A%20%E5%9D%97%E5%86%85%E5%8E%9F%20RoPE%22%5D%0A%20%20Q%20--%3E%20S%5B%22successive%3A%20%E7%9B%B8%E9%82%BB%E5%9D%97%22%5D%0A%20%20Q%20--%3E%20E%5B%22inter%3A%20%E6%9B%B4%E6%97%A9%E5%9D%97%22%5D%0A%20%20I%20--%3E%20M%5B%22%E7%9B%B8%E5%AF%B9%E4%BD%8D%E7%BD%AE%E7%9F%A9%E9%98%B5%20M%22%5D%0A%20%20S%20--%3E%20M%0A%20%20E%20--%3E%20M%0A%20%20M%20--%3E%20FA%5B%22FlashAttention%20%E5%88%86%E5%9D%97%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("标准 RoPE 的 \\(M\\) 是 Toeplitz：同一条对角线上 \\(\\Delta\\) 相同。"),t("span",{class:"marginnote"},"术语翻译：Toeplitz 矩阵就是「沿对角线数值相同」的矩阵——相对位置表天然长这样，因为 \\(\\Delta=P_q[i]-P_k[j]\\) 只依赖两个下标之差。可以把它想成一张距离表：第 3 行第 7 列与第 10 行第 14 列的「隔多远」完全一样。长文本的问题就出在表的最右上角出现了模型没见过的远距离。"),e("长度一过 \\(c\\)，右上角全是未见过的大 \\(\\Delta\\)。")],-1)),(o(),l(E,null,{default:n(()=>[r(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BA%8F%E5%88%97%E9%95%BF%E8%B6%85%E8%BF%87%E8%AE%AD%E7%BB%83%E7%AA%97%20c%22%5D%20--%3E%20A%5B%22%E6%A0%87%E5%87%86%20RoPE%EF%BC%9A%E5%A4%A7%20%CE%94%20%E6%9C%AA%E8%A7%81%E8%BF%87%22%5D%0A%20%20A%20--%3E%20A1%5B%22PPL%20%E5%B4%A9%22%5D%0A%20%20L%20--%3E%20B%5B%22PI%20%2F%20NTK%EF%BC%9A%E6%95%B4%E8%A1%A8%E9%99%A4%E4%BB%A5%20s%22%5D%0A%20%20B%20--%3E%20B1%5B%22%CE%94%20%E9%83%BD%E5%9C%A8%E7%AA%97%E5%86%85%EF%BC%8C%E4%BD%86%E5%88%86%E8%BE%A8%E4%B8%8D%E5%87%BA%E8%BF%9C%E8%BF%91%22%5D%0A%20%20L%20--%3E%20C%5B%22DCA%EF%BC%9A%E6%8C%89%E5%9D%97%E5%85%B3%E7%B3%BB%E5%88%87%E6%8D%A2%E4%B8%89%E5%A5%97%E5%9D%90%E6%A0%87%22%5D%0A%20%20C%20--%3E%20C1%5B%22%CE%94%20%E4%BB%8D%E5%B0%8F%E4%BA%8E%20c%EF%BC%8C%E5%9D%97%E7%BA%A7%E8%BF%9C%E8%BF%91%E5%8F%AF%E5%8C%BA%E5%88%86%22%5D%0A%20%20C1%20--%3E%20OK%5B%22PPL%20%E4%B8%8E%20passkey%20%E7%AB%99%E4%BD%8F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">这张图回答「为什么训练免费缩放会失败」：PI 把距离全部压缩后，「隔 3 个块」和「隔 30 个块」的坐标差距也被压得几乎为零，模型分不清远近；DCA 不压原始距离，而是给不同块关系各发一套仍在窗内的坐标系，兼顾「见过」和「分得清」。</span>PI 把整张 \\(M\\) 除以 \\(s\\)，未见过的消失，分辨率也消失。DCA 把 \\(M\\) 划成块状区域，每块用不同规则生成仍小于 \\(c\\) 的 \\(\\Delta\\)，近似「短窗相对几何的拼接」。块内同构是局部质量的硬保证；inter 提供可区分的块级坐标；successive 防止块边界上的相位跳变进入从未见过的区域。</p><p>与 Self-Extend 的阶梯相比：阶梯没有「当前块完整 \\(c\\)」的硬保证，除非把邻窗设成块长且不再分组——那已滑向 intra 特例，却仍缺显式 inter 坐标与相邻通道。与 LM-Infinite 相比：DCA 默认仍看更早块内容，中间历史以块级坐标参加 softmax，而不是 Λ 形丢掉。代价是计算仍随可见键数涨；再对早块稀疏就离开原方案，变成另一种系统。块长 \\(s\\) 应贴近训练窗 \\(c\\)：切成远小于 \\(c\\) 的碎片，intra 的同构优势消失，只剩实现复杂度。</p><p><span class="marginnote">先各自 softmax 再加权，与一次大 softmax 不等价。接 FlashAttention 时应在 logits 域合并，或接受近似并在消融里写清楚。这是 70B 实验能复现与否的常见坑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DCA 不给常数内存。KV 仍按 \\(n\\) 增长。<span class="marginnote">常见误区：初学者容易把「分块注意力」等同于「省显存」。DCA 只重写位置坐标，一个键都不删——100k token 的 KV cache 照样按线性涨。省显存要靠 KV 量化、稀疏丢弃等另一类手段，两者别混为一谈。</span>块长 \\(s\\) 与 \\(c\\) 错位会让 intra 也偏离训练窗。对已经原生长窗预训练、相对位置本就正确的模型，再套三套 \\(\\phi\\) 可能负优化。ALiBi 没有可切换的旋转 \\(\\phi\\)。</p><p>正交性是双刃剑：与 PI/NTK 同开时，必须固定顺序——先频率缩放还是先分块——并分开消融，否则 192k passkey 变绿无法归因。Qwen 系产品后来常把 YaRN 与分块注意力一起宣传，读发布材料时要当成补丁叠补丁。</p><p><span class="marginnote">70B 无训练能跑 100k，依赖 FlashAttention 与多卡显存，不是算法把复杂度降到线性。复现 7B 的 PPL 表不能代替 70B 的理解任务表：原文强调小模型验证不够。</span></p><h3 id="评测协议" tabindex="-1">评测协议 <a class="header-anchor" href="#评测协议" aria-label="Permalink to &quot;评测协议&quot;">​</a></h3><p>语言建模：4k 底座扩到 32k 以上且 PPL 几乎不升，用来打训练免费 PI/NTK。passkey：含叠在 32k 续训模型上再扩到 192k。理解：QA 与摘要，zero-shot 与 few-shot；并与 Llama2 Long 一类续训模型比。自造「论文当上下文」的题用来展示未污染的长依赖。短窗质量应仍接近底座，因为 intra 未改训练几何。跨块针必须进表：针在第 \\(j\\) 块、问句在最后一块，只测末块会虚高任何块内同构方案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DCA 原文在训练免费设定下重写相对位置矩阵，而不是缩放 RoPE 下标或基数。</li><li>三套边：块内同构、块间可区分的远距映射、相邻块修补接缝。</li><li>Llama2 70B 无续训超过 100k；可与已有 32k 缩放检查点正交叠加。</li><li>依赖 FlashAttention 级实现；不降低 KV 线性增长。</li><li>出处：An 等，<em>Training-Free Long-Context Scaling of Large Language Models</em>，2024，arXiv:2402.17463，代码 ChunkLlama。对照 Jin 等 Self-Extend、Peng 等 YaRN、Chen 等 PI。</li></ul>',11))])}const C=A(h,[["render",d]]);export{g as __pageData,C as default};
